import{_ as t,o as n,c as i,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const m=JSON.parse('{"title":"Ceph Crimson/SeaStore 2021-07-07","description":"","frontmatter":{"title":"Ceph Crimson/SeaStore 2021-07-07","date":"2021-07-07T00:00:00.000Z","updated":"2021-08-25T00:00:00.000Z","tags":["Ceph","分布式存储","Crimson项目","MLIS案例分析","Extent Placement Manager"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Crimson_SeaStore_2021-07-07.md","filePath":"posts/2021/Ceph_Crimson_SeaStore_2021-07-07.md","lastUpdated":1780460162000}'),r={name:"posts/2021/Ceph_Crimson_SeaStore_2021-07-07.md"};function a(l,e,p,s,_,S){return n(),i("div",null,[...e[0]||(e[0]=[o("<p>在2021年7月7日的Ceph Crimson/SeaStore会议中，研发团队主要讨论了以下几个关键议题：</p><ol><li><p><strong>Crimson项目的清理和讨论</strong>：Aaron分享了Crimson项目中的随机清理工作，并讨论了与Jihan关于扩展分配管理器的PR。</p></li><li><p><strong>IOCTL和控制支持的补丁更新</strong>：Aaron正在开发Ceph的IOCTL和控制支持的下一个补丁版本，并已提交并接收了一些评审意见。</p></li><li><p><strong>Extent内容的更新问题</strong>：Aaron报告了一个关于Extent内容更新的问题，特别是在并发操作中，可能导致错误的地址获取。</p></li><li><p><strong>MLIS案例分析</strong>：Riddick分享了关于MLIS案例的分析，指出问题可能与消息处理有关，特别是在OSD重启时可能发生的竞态条件。</p></li><li><p><strong>Extent Placement Manager的修改</strong>：讨论了如何处理Extent的写入和日志记录。</p></li><li><p><strong>C-Store性能分析</strong>：正在进行C-Store的性能分析，并尝试添加矩阵以帮助诊断性能问题。</p></li></ol><p>会议中的决定事项包括：</p><ul><li>Aaron将继续优化Extent内容的更新问题，并寻找更稳定的解决方案。</li><li>Riddick将继续分析MLIS案例，特别是关注消息处理和OSD重启时的竞态条件。</li><li>对于Extent Placement Manager的修改，将继续进行多设备支持的实现。</li></ul><p>后续行动计划包括：</p><ul><li>Aaron将提交更新的补丁版本，并继续在Segment Manager中实现接口。</li><li>Riddick将深入研究MLIS案例，并寻找可能的解决方案。</li><li>所有参会者将继续关注各自负责的模块，确保Ceph的稳定性和性能优化。</li></ul><p>此外，会议还讨论了消息处理的防御性编程以及如何在集群中处理可能的错误消息。</p><p>改进点：</p><ul><li>确保所有关键议题、讨论内容、决定事项和后续行动计划都被包含在总结中。</li><li>保留了原字幕中的英文关键词，如Crimson、MLIS、Extent Placement Manager等。</li><li>简化了部分描述，以提高可读性。</li></ul>",9)])])}const d=t(r,[["render",a]]);export{m as __pageData,d as default};
